namespace scratchbird::engine::sblr{namespace{void p(std::vector<uint8_t>&o,uint64_t v,size_t n){for(size_t i=0;i<n;++i)o.push_back((v>>(8*i))&255);}uint64_t g(const uint8_t*b,size_t n){uint64_t v=0;for(size_t i=0;i<n;++i)v|=uint64_t(b[i])<<(8*i);return v;}template<class T>bool nz(const T&x){return std::any_of(x.begin(),x.end(),[](auto v){return v;});}std::vector<uint8_t>hd(const char*m,size_t n){std::vector<uint8_t>o(m,m+4);p(o,1,2);p(o,n,2);p(o,n,4);p(o,0,4);return o;}bool vh(const uint8_t*b,size_t n,const char*m,size_t x){return b&&n==x&&std::equal(b,b+4,m)&&g(b+4,2)==1&&g(b+6,2)==x&&g(b+8,4)==x&&std::all_of(b+12,b+16,[](auto v){return !v;});}AdvisoryLockSha sh(const uint8_t*b,size_t n){const char*d="ScratchBird.SblrAdvisoryLockReleaseDescriptor.V1";std::vector<uint8_t>x(d,d+std::strlen(d));x.insert(x.end(),b,b+n);return scratchbird::core::hash::ComputeSha256Digest(x).digest;}}
std::vector<uint8_t>EncodeSblrAdvisoryLockReleaseRequestV1(const SblrAdvisoryLockReleaseRequestV1&v){if(!nz(v.receipt)||!v.occurrence||!v.release_occurrence)return{};auto o=hd("ALRQ",64);o.insert(o.end(),v.receipt.begin(),v.receipt.end());p(o,v.occurrence,8);p(o,v.release_occurrence,4);o.insert(o.end(),20,0);return o;}bool DecodeSblrAdvisoryLockReleaseRequestV1(const uint8_t*b,size_t n,SblrAdvisoryLockReleaseRequestV1*out,std::string*d){if(!out||!vh(b,n,"ALRQ",64)||std::any_of(b+44,b+64,[](auto v){return v;})){if(d)*d="ALRQ invalid";return false;}SblrAdvisoryLockReleaseRequestV1 v;std::copy_n(b+16,16,v.receipt.begin());v.occurrence=g(b+32,8);v.release_occurrence=g(b+40,4);if(EncodeSblrAdvisoryLockReleaseRequestV1(v).empty())return false;*out=v;return true;}
std::vector<uint8_t>EncodeSblrAdvisoryLockReleaseDescriptorV1(const SblrAdvisoryLockReleaseDescriptorV1&v,bool op){if(!nz(v.canonical_body)||!v.availability_generation)return{};auto o=hd(op?"ALRO":"ALRD",256);o.insert(o.end(),v.canonical_body.begin(),v.canonical_body.end());auto e=sh(o.data()+16,200);if(nz(v.evidence)&&v.evidence!=e)return{};o.insert(o.end(),e.begin(),e.end());p(o,v.availability_generation,8);return o;}bool DecodeSblrAdvisoryLockReleaseDescriptorV1(const uint8_t*b,size_t n,SblrAdvisoryLockReleaseDescriptorV1*out,std::string*d,bool op){if(!out||!vh(b,n,op?"ALRO":"ALRD",256)){if(d)*d="advisory lock release descriptor invalid";return false;}SblrAdvisoryLockReleaseDescriptorV1 v;std::copy_n(b+16,200,v.canonical_body.begin());std::copy_n(b+216,32,v.evidence.begin());v.availability_generation=g(b+248,8);if(EncodeSblrAdvisoryLockReleaseDescriptorV1(v,op).empty())return false;*out=v;return true;}}
